#!/bin/bash
# make_sd_from_xsa.sh — microSD files WITHOUT Vitis: U-Boot SPL (instead of the FSBL) from system.xsa
#                       (runs on the DGX Spark, after build_linux.sh)
#
#   ./make_sd_from_xsa.sh /path/to/system.xsa
#
# system.xsa (from vivado/build.tcl) is a zip with ps7_init_gpl.c/.h (DDR3 / MIO / clocks of the
# AC7010C, generated by Vivado) and the bitstream. U-Boot SPL runs that ps7_init, loads u-boot.img,
# U-Boot loads dusk.bit into the PL and boots Linux. Output -> ../sd_card_spl/:
#   BOOT.bin (SPL)  u-boot.img  dusk.bit  zImage  system.dtb
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
WORK=${WORK:-$HOME/opt/dusk_zynq_linux}
XSA=$(readlink -f "${1:?usage: $0 system.xsa}")
export PATH=$WORK/arm-gnu-toolchain-13.3.rel1-aarch64-arm-none-linux-gnueabihf/bin:$PATH
export ARCH=arm CROSS_COMPILE=arm-none-linux-gnueabihf-
OUT=$HERE/../sd_card_spl
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

python3 -I - "$XSA" "$TMP" <<'PY'
import sys, zipfile, os
z = zipfile.ZipFile(sys.argv[1]); out = sys.argv[2]
want = {"ps7_init_gpl.c", "ps7_init_gpl.h"}
for n in z.namelist():
    b = os.path.basename(n)
    if b in want or b.endswith(".bit"):
        dst = os.path.join(out, "dusk.bit" if b.endswith(".bit") else b)
        with open(dst, "wb") as f:
            f.write(z.read(n))
        print("  from xsa:", n, "->", os.path.basename(dst))
missing = [w for w in want | {"dusk.bit"} if not os.path.exists(os.path.join(out, w))]
if missing:
    sys.exit("xsa is missing: " + ", ".join(missing))
PY

cd "$WORK/u-boot-xlnx"
mkdir -p board/xilinx/zynq/zynq-dusk-boom
cp "$TMP/ps7_init_gpl.c" "$TMP/ps7_init_gpl.h" board/xilinx/zynq/zynq-dusk-boom/
taskset -c 0-9 make -s -j10 NO_SDL=1
test -f spl/boot.bin && test -f u-boot.img
mkdir -p "$OUT"
cp spl/boot.bin "$OUT/BOOT.bin"
cp u-boot.img "$OUT/"
cp "$TMP/dusk.bit" "$OUT/dusk.bit"
cp "$HERE/../sd/zImage" "$HERE/../sd/system.dtb" "$OUT/"
echo "microSD files (SPL path) in $OUT:"; ls -la "$OUT"
echo "FAT32 first partition, copy all files to the top folder; module J13 -> SD"
